"use strict";(globalThis.webpackChunkgrc||=[]).push([[3835],{21013(e){e.exports=JSON.parse('{"citeKey":"lu2024chrome","slug":"lu-2024-chrome-1321","title":"CHROME: Concurrency-Aware Holistic Cache Management Framework with Online Reinforcement Learning","authors":["X. Lu","H. Najafi","J. Liu","X.-H. Sun"],"venue":"The 30th IEEE International Symposium on High-Performance Computer Architecture (HPCA 2024), Edinburgh, Scotland","type":"Conference","entryType":"inproceedings","date":"March, 2024","year":2024,"era":"iit","month":3,"doi":"10.1109/hpca57654.2024.00090","abstract":"Cache management is a critical aspect of computer architecture, encompassing techniques such as cache replace- ment, bypassing, and prefetching. Existing research has often fo- cused on individual techniques, overlooking the potential benefits of joint optimization. Moreover, many of these approaches rely on static and intuition-driven policies, limiting their performance under complex and dynamic workloads. To address these chal- lenges, this paper introduceesCHROME,a novelty aware cache management framework. CHROME takes a holistic approach by seamlessly integrating intelligent cache replacement and bypassing with pattern-based prefetching. By leveraging online reinforcement learning, CHROME dynamically adapts cache decisions based on multiple program features and applies a reward for each decision that considers the accuracy of the action and the system-level feedback information. Our performance evaluation demonstrates that CHROME outperforms current state-of-the-art schemes, exhibiting significant improvements in cache management. Notably, CHROME achieves a remarkable performance boost of up to 13.7% over the traditional LRU method in multi-core systems with only modest overhead.","hasAbstract":true,"lede":"To address these chal- lenges, this paper introduceesCHROME,a novelty aware cache management framework.","links":{"pdf":"https://grc.iit.edu/papers/2024/lu-2024-chrome-1321.pdf","slides":"https://grc.iit.edu/papers/2024/lu-2024-chrome-1321-slides.pdf"},"tags":["Memory Architecture","Cache Management","Optimization of Memory Architectures","UniMCC"],"_projectIds":["optmem","unimcc","memory-access-obfuscation"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["unimcc","memory-access-obfuscation","optmem"],"memberAuthors":["lu-xiaoyang","sun-xian-he"],"funding":[{"agency":"NSF","award":"CCF-2008000","projectId":"optmem"},{"agency":"NSF","award":"CNS-1956229"},{"agency":"NSF","award":"IIS-2331908"},{"agency":"NSF","award":"CNS-2310422","projectId":"unimcc"},{"agency":"NSF","award":"CNS-2152497","projectId":"memory-access-obfuscation"}]}')}}]);